/**
 * A call at a stop: where it is and when the vehicle arrives and leaves.
 * The fields follow the same rules as those of a ``Departure``.
 */
public struct Stopover: Equatable, Hashable, Codable {
    /**
     * The stop, platform or other place.
     */
    public var stop: Location
    /**
     * The arrival time according to the timetable.
     */
    public var scheduledArrival: UtcTime?
    /**
     * The predicted arrival time. `nil` if the server has no prediction.
     */
    public var realtimeArrival: UtcTime?
    /**
     * The departure time according to the timetable.
     */
    public var scheduledDeparture: UtcTime?
    /**
     * The predicted departure time. `nil` if the server has no prediction.
     */
    public var realtimeDeparture: UtcTime?
    /**
     * The platform according to the timetable.
     */
    public var scheduledPlatform: String?
    /**
     * The platform as far as the server knows now.
     */
    public var realtimePlatform: String?
    /**
     * Whether the vehicle skips this stop although the timetable has it.
     */
    public var cancelled: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The stop, platform or other place.
         */stop: Location, 
        /**
         * The arrival time according to the timetable.
         */scheduledArrival: UtcTime?, 
        /**
         * The predicted arrival time. `nil` if the server has no prediction.
         */realtimeArrival: UtcTime?, 
        /**
         * The departure time according to the timetable.
         */scheduledDeparture: UtcTime?, 
        /**
         * The predicted departure time. `nil` if the server has no prediction.
         */realtimeDeparture: UtcTime?, 
        /**
         * The platform according to the timetable.
         */scheduledPlatform: String?, 
        /**
         * The platform as far as the server knows now.
         */realtimePlatform: String?, 
        /**
         * Whether the vehicle skips this stop although the timetable has it.
         */cancelled: Bool) {
        self.stop = stop
        self.scheduledArrival = scheduledArrival
        self.realtimeArrival = realtimeArrival
        self.scheduledDeparture = scheduledDeparture
        self.realtimeDeparture = realtimeDeparture
        self.scheduledPlatform = scheduledPlatform
        self.realtimePlatform = realtimePlatform
        self.cancelled = cancelled
    }

    

}

